from datetime import date, timedelta


class LeaveTracker:
    def __init__(self, days_per_year: int = 26, holidays: list[date] | None = None) -> None:
        self.days_per_year = days_per_year
        self.holidays = set(holidays) if holidays else set()
        # Track used days keyed by (employee, year)
        self._used: dict[tuple[str, int], int] = {}

    def _is_leave_day(self, day: date) -> bool:
        # Weekends: Saturday (5) and Sunday (6)
        if day.weekday() >= 5:
            return False
        if day in self.holidays:
            return False
        return True

    def _count_leave_days(self, start: date, end: date) -> tuple[int, dict[int, int]]:
        """Count leave days between start and end, grouped by year."""
        per_year: dict[int, int] = {}
        current = start
        while current <= end:
            if self._is_leave_day(current):
                per_year[current.year] = per_year.get(current.year, 0) + 1
            current += timedelta(days=1)
        return sum(per_year.values()), per_year

    def remaining(self, employee: str, year: int) -> int:
        used = self._used.get((employee, year), 0)
        return self.days_per_year - used

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        if end < start:
            raise ValueError("End date cannot be before start date.")

        total_days, per_year = self._count_leave_days(start, end)

        # Validate that each year has enough remaining
        for year, needed in per_year.items():
            if needed > self.remaining(employee, year):
                raise ValueError(
                    f"Insufficient leave for {employee} in {year}: "
                    f"needed {needed}, remaining {self.remaining(employee, year)}."
                )

        # Apply the usage
        for year, needed in per_year.items():
            key = (employee, year)
            self._used[key] = self._used.get(key, 0) + needed

        return total_days
